class Solution {
public:
    string getPermutation(int n, int k) {
        vector<int> nums;
        for (int i = 1; i <= n; i++) {
            nums.push_back(i);
        }

        return solve(nums, k);
    }

private:
    string solve(vector<int>& nums, int k) {
        if (nums.size() == 1) {
            return to_string(nums[0]);
        }

        int fact = 1;
        for (int i = 1; i < nums.size(); i++) {
            fact *= i;
        }

        k = k - 1;
        int index = k / fact;
        k = k % fact;

        int num = nums[index];
        nums.erase(nums.begin() + index);

        return to_string(num) + solve(nums, k + 1);
    }
};

