    int solve(string &s, int &i) {
        long long result = 0;
        long long num = 0;
        int sign = 1;

        while (i < s.size()) {

            if (isdigit(s[i])) {
                num = num * 10 + (s[i] - '0');
            }

            else if (s[i] == '+') {
                result += sign * num;
                num = 0;
                sign = 1;
            }

            else if (s[i] == '-') {
                result += sign * num;
                num = 0;
                sign = -1;
            }

            else if (s[i] == '(') {
                i++;
                num = solve(s, i);
            }

            else if (s[i] == ')') {
                result += sign * num;
                return result;
            }

            i++;
        }

        result += sign * num;
        return result;
    }

