class Solution {
public:
    int uniquePaths(int m, int n) {
        if (m == 1 || n == 1) return 1;
        if (m > n) swap(m, n);
        long long temp = 1, res = 1;
        for (int i = 1; i < m; i++) temp *= i;
        for (int i = n; i < m + n - 1; i++) res *= i;
        return res / temp;
    }
};

